def solve(nums):
    # Handle short lists
    if len(nums) <= 1:
        return list(nums)
    n = len(nums)
    # Find first index i from right where nums[i] < nums[i+1]
    i = n - 2
    while i >= 0 and nums[i] >= nums[i+1]:
        i -= 1
    if i == -1:
        # nums is in descending order, return sorted ascending
        return sorted(nums)
    # Find smallest element greater than nums[i] to the right
    j = n - 1
    while nums[j] <= nums[i]:
        j -= 1
    # Create a copy to avoid mutating input
    res = list(nums)
    # Swap
    res[i], res[j] = res[j], res[i]
    # Reverse suffix
    res[i+1:] = reversed(res[i+1:])
    return res

