def solve(n, edges):
    """Return the lexicographically smallest topological ordering of a DAG with n nodes (0..n-1).
    If a cycle exists, return an empty list.
    Uses a min-heap to always select the smallest available node.
    """
    from heapq import heappush, heappop
    adj = [[] for _ in range(n)]
    indeg = [0] * n
    for a, b in edges:
        # assume valid indices as per spec; ignore invalid just in case
        if 0 <= a < n and 0 <= b < n:
            adj[a].append(b)
            indeg[b] += 1
    heap = []
    for i in range(n):
        if indeg[i] == 0:
            heappush(heap, i)
    order = []
    while heap:
        u = heappop(heap)
        order.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                heappush(heap, v)
    if len(order) != n:
        return []
    return order

